import React, { useState } from 'react';
import { ChevronDown, ChevronRight, ShieldCheck, AlertCircle, Sparkles } from 'lucide-react';

const initialFaqItems = [
  {
    id: 1,
    question: "How do I schedule a consultation?",
    answer: "Our intake forms are designed to streamline the process. Simply select your preferred area of law, provide basic contact info, and a member of our team will reach out within 24 hours to confirm your appointment. For urgent matters, please call our direct line (555) 123-4567.",
    icon: Sparkles,
  },
  {
    id: 2,
    question: "What fees can I expect?",
    answer: "We offer competitive rates based on the complexity of your case and the time required. Initial consultations are complimentary. We provide detailed fee agreements upfront and strive to keep our billing transparent. For more information, visit our 'Fees & Policies' section.",
    icon: ShieldCheck,
  },
  {
    id: 3,
    question: "Do you handle international cases?",
    answer: "Absolutely! Hartwell & Sawyer specializes in cross-border litigation and corporate restructuring. We have partners worldwide and can assist with filings in multiple jurisdictions. Contact us for a confidential assessment.",
    icon: AlertCircle,
  },
  {
    id: 4,
    question: "Is my data secure?",
    answer: "Client confidentiality is paramount. We comply with GDPR and have implemented multi-factor authentication, end-to-end encryption for communications, and quarterly security audits. All staff are vetted and signed NDA’s.",
    icon: ShieldCheck,
  },
  {
    id: 5,
    question: "What if I need help outside of regular hours?",
    answer: "Our emergency contact line is active 24/7 for life-threatening situations or urgent legal crises. For non-emergencies, reply to your case manager or use the in-app chat feature. We’ll address your issue as swiftly as possible.",
    icon: Sparkles,
  },
];

export default function Faq() {
  const [expanded, setExpanded] = useState<number | null>(null);

  const toggle = (id: number) => {
    if (expanded === id) {
      setExpanded(null);
    } else {
      setExpanded(id);
    }
  };

  return (
    <div className="w-full max-w-6xl mx-auto p-6 sm:p-10 bg-slate-950 text-slate-100">
      <div className="flex flex-col sm:flex-row justify-between items-center mb-12">
        <div>
          <h2 className="text-2xl sm:text-3xl font-bold tracking-tight text-slate-100 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500 bg-clip-text text-transparent">
            Frequently Asked Questions
          </h2>
          <p className="mt-3 text-slate-400 text-sm max-w-md">Directly from our legal experts to help you navigate.</p>
        </div>
        <div className="mt-6 sm:mt-0 sm:ml-6">
          <button
            type="button"
            className="inline-flex items-center justify-center px-3 py-2 rounded-xl bg-white/5 border border-white/10 text-slate-300 hover:text-slate-200 hover:bg-white/10 transition-colors duration-200 font-medium text-xs shadow-inner active:scale-95"
          >
            <span className="mr-1.5">Ask a Question</span>
            <span className="w-3 h-3 rounded-full bg-indigo-400 text-white shadow-lg shadow-indigo-500/30 transition-all duration-200" />
          </button>
        </div>
      </div>

      <div className="space-y-6">
        {initialFaqItems.map((item) => {
          const isExpanded = expanded === item.id;
          return (
            <div key={item.id} className="group relative rounded-xl border border-white/10 bg-white/5 p-6 transition-all duration-300 hover:border-white/20 hover:bg-white/10">
              <div className="flex items-start justify-between pb-4 sm:pb-6">
                <div className="flex items-start space-x-3">
                  <div className="flex items-center justify-center w-9 h-9 rounded-xl bg-indigo-500/10 text-indigo-400 shadow-inner text-xl font-bold">
                    <item.icon />
                  </div>
                  <div>
                    <h3 className="text-slate-100 text-sm sm:text-base font-semibold tracking-tight group-hover:text-indigo-300">
                      {item.question}
                    </h3>
                    <p className="mt-1 text-slate-400 text-sm">{item.answer}</p>
                  </div>
                </div>
                <div className="flex items-center sm:justify-end text-slate-400 group-hover:text-slate-200">
                  <button
                    type="button"
                    className="p-1 rounded-xl text-slate-400 hover:text-slate-200 transition-colors duration-200"
                    onClick={() => toggle(item.id)}
                  >
                    <ChevronRight className={`w-5 h-5 transform group-hover:rotate-180 ${isExpanded ? 'rotate-90' : ''}`} />
                  </button>
                </div>
              </div>
            </div>
          );
        })}
      </div>
    </div>
  );
}

import React, { useState } from 'react';
import { Scale, Gavel, ShieldCheck, Users, FileText, Landmark, Sparkles, CheckCircle2, Sparkle, ChevronRight, ArrowRight, ExternalLink } from 'lucide-react';

const practiceAreas = [
  {
    id: 1,
    name: 'Business & Corporate',
    icon: Scale,
    description: 'Strategic guidance for startups, M&A, and intellectual property.',
    buttonLabel: 'Explore Services',
    href: '#'
  },
  {
    id: 2,
    name: 'Family Law',
    icon: Users,
    description: 'Compassionate representation for divorce, custody, and guardianship.',
    buttonLabel: 'Learn More',
    href: '#'
  },
  {
    id: 3,
    name: 'Real Estate',
    icon: Landmark,
    description: 'Securing your investment with closing assistance and zoning compliance.',
    buttonLabel: 'View Listings',
    href: '#'
  },
  {
    id: 4,
    name: 'Personal Injury',
    icon: ShieldCheck,
    description: 'Fighting for full compensation from negligent parties and insurance companies.',
    buttonLabel: 'Get Help',
    href: '#'
  },
  {
    id: 5,
    name: 'Litigation & Trial Practice',
    icon: Gavel,
    description: 'Experienced litigators ready for the toughest cases.',
    buttonLabel: 'Schedule Case Review',
    href: '#'
  },
  {
    id: 6,
    name: 'Estate Planning',
    icon: Sparkles,
    description: 'Tailoring wills, trusts, and probate solutions for your legacy.',
    buttonLabel: 'Start Planning',
    href: '#'
  }
];

export default function PracticeAreas() {
  const [hovered, setHovered] = useState(null);

  return (
    <section id="practices" className="w-full bg-slate-950 text-slate-100 py-24 sm:py-32">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8">
        {/* Decorative gradient bar */}
        <div className="absolute left-1/2 -translate-x-1/2 top-1/3 w-1/2 h-1 bg-gradient-to-r from-indigo-500 via-purple-500 to-pink-500" />

        <div className="relative z-10 text-center">
          <h2 className="text-3xl font-bold sm:text-4xl tracking-tight text-slate-100 font-display mb-4">
            Our Core Practice Areas
          </h2>
          <p className="text-slate-400 max-w-md mx-auto mb-10">
            At Hartwell & Sawyer, we leverage deep industry expertise and cutting-edge strategies to deliver unparalleled legal solutions.
          </p>
        </div>

        {/* Cards Grid */}
        <div className="grid grid-cols-1 sm:grid-cols-2 lg:grid-cols-3 gap-6 sm:gap-8 max-w-md mx-auto pb-20 sm:pb-24">
          {practiceAreas.map((area) => {
            const Icon = area.icon;
            return (
              <div
                key={area.id}
                className="relative overflow-hidden rounded-2xl bg-white/5 p-6 transition-all duration-300 hover:scale-[1.02] hover:shadow-2xl shadow-indigo-950/30"
                onMouseEnter={() => setHovered(area.id)}
                onMouseLeave={() => setHovered(null)}
              >
                <div className="absolute -inset-1 bg-indigo-600/20 rounded-2xl" />
                <div className="relative flex items-start justify-between pb-8">
                  <div className="flex items-start gap-3">
                    <Icon className="w-6 h-6 text-indigo-400 animate-pulse" />
                    <div>
                      <h3 className="text-lg font-semibold text-slate-100">{area.name}</h3>
                      <p className="text-sm text-slate-400">{area.description}</p>
                    </div>
                  </div>
                  <div className="flex items-center gap-2">
                    {area.id === hovered && (
                      <a href={area.href} target="_blank" rel="noopener noreferrer" className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium bg-indigo-600/10 text-indigo-300 border border-indigo-600/20 hover:bg-indigo-600/20 active:bg-indigo-600/30 transition-all duration-150">
                        <Sparkle className="w-3.5 h-3.5" /> Explore
                      </a>
                    )}
                    <span className="inline-flex items-center gap-1.5 px-3 py-1 rounded-full text-xs font-medium bg-slate-900/20 text-slate-400 border border-slate-900/30 hover:bg-slate-900/30 active:bg-slate-900/40 transition-all duration-150">
                      <ArrowRight className="w-3.5 h-3.5" /> More Info
                    </span>
                  </div>
                </div>
              </div>
            );
          })}
        </div>
      </div>
    </section>
  );
}
